    $$$TRACE("Inside getValuesUsingStringRequest()")
	#dim tSC=$$$OK
	#dim pSearchLevel=1	
	#dim pAttr As %String=""
	//Ldap search return is of type %Net.LDAP.Client.Entries
	#dim pEntries As %Net.LDAP.Client.Entries
	#dim ldapEntry As %Net.LDAP.Client.Entry
	#dim valueList As %Net.LDAP.Client.ValueList
	// Parameter to be passed to Ldap Search API
	#dim pFilterString As %String=pRequest.StringValue

	#dim keyEntries,keyEntry,keyValueList As %String=""
	#dim attrValue As %String=""
	$$$TRACE("Ldap Search Filter "_pFilterString)	
	if (..LdapSearchScope'=""){
		set pSearchLevel=..LdapSearchScope
	}

	If (..LdapAttributes'=""){
		set pAttr=..LdapAttributes
	}

	set pResponse=##class(IHC.ITF.ITFCOMMON.DStruc.LdapSearchResponse).%New()


	$$$TRACE(" Filter: "_pFilterString_", pSearchlevel: "_pSearchLevel_", ATTR: "_pAttr)

	// Call LDAP search
	if ..Adapter.Connected { 
      $$$TRACE("Ldap adapter is connected... ")
	set tSC=..Adapter.Search(.pEntries,pSearchLevel,pFilterString,pAttr)
	$$$TRACE(" Returned Status "_tSC)


	if (tSC){

		$$$TRACE(" PENTRIES *"_$G(pEntries,"Default")_"*")

		set keyEntries="" 
		 do {
			 set ldapEntry=pEntries.GetNext(.keyEntries)
		  	 $$$TRACE(" Got LDAP Entry "_ldapEntry_" keyEntries `"_keyEntries)
		  	 quit:keyEntries=""
		  	 set keyEntry=""
		 	 do  {
			 	 set valueList=ldapEntry.GetNext(.keyEntry)
			 	 quit:keyEntry=""
			 	 set strValue=""
				 $$$TRACE(" ValueList "_valueList_" for key "_keyEntry)
				 set keyValueList=""
				 //set pResponse.StringValue="Key Value= "_keyEntry_" Value : "
				 do {
					set attrValue=valueList.GetNext(.keyValueList)
			       	quit:keyValueList=""
			       	$$$TRACE(" VALUE "_attrValue)

			       	if (strValue="") {
				        s strValue=attrValue
			        }
			        else {
				        s strValue=strValue_","_attrValue
			        }
			  	}while (keyValueList'="")
				if (strValue'=""){
					do pResponse.ldapReturnValues.SetAt(strValue,keyEntry)
				}
		 	 }while (keyEntry'="")

		 }while (keyEntries'="")
	}
	}
	else {
		$$$TRACE("Ldap adapter is not connected... ")
	}
	quit tSC

#dim tSC=$$$OK
#dim pAttr As %String=""

// Parameter to be passed to Ldap Search API
#dim pFilterString As %String=pRequest.searchString

#dim keyEntries,keyEntry,keyValueList As %String=""
#dim pSearchLevel As %String=""
#dim pDN As %String=""


If (pRequest.attrList'=""){
	set pAttr=pRequest.attrList
}elseif (..LdapAttributes'=""){
	set pAttr=..LdapAttributes
}

If (pRequest.searchScope'=""){
	set pSearchLevel=pRequest.searchScope
} 

set pDN=pRequest.DN

set tSC=..ldapSearch(pAttr,pFilterString,pSearchLevel,pDN,.pResponse,1)



quit tSC

